/** Writes one bounded, exact pre-restore snapshot; failures prevent destructive restore. */
export function saveRecoverySnapshot(storage: Storage): void {
  const current = storage.getItem(getFinanceStorageKey())
  if (!current) return
  const snapshot = JSON.stringify({ savedAt: new Date().toISOString(), persisted: JSON.parse(current) })
  storage.setItem(getFinanceRecoveryKey(), snapshot)
  if (storage.getItem(getFinanceRecoveryKey()) !== snapshot) throw new Error('The recovery backup could not be verified. Nothing was replaced.')
}

